def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n == 2:
        if history[0][1] == 'C' and history[1][1] == 'C':
            return 'C'
        if history[0][1] == 'D' and history[1][1] == 'D':
            return 'D'
        return 'D' if history[1][1] == 'D' else 'C'

    opp_hist = [h[1] for h in history]
    my_hist = [h[0] for h in history]
    opp_last = opp_hist[-1]
    my_last = my_hist[-1]

    opp_coop = sum(1 for a in opp_hist if a == 'C')
    opp_defect = n - opp_coop
    opp_rate = opp_coop / n

    w = 12 if n >= 12 else n
    recent_opp = opp_hist[-w:]
    recent_coop = sum(1 for a in recent_opp if a == 'C')
    recent_rate = recent_coop / w

    def tail_run(val):
        k = 0
        for a in reversed(opp_hist):
            if a == val:
                k += 1
            else:
                break
        return k

    opp_def_streak = tail_run('D')
    opp_coop_streak = tail_run('C')

    # Opponent completely cooperative: exploit in late game, probe sparsely.
    if opp_defect == 0:
        remaining = 100 - n
        if remaining <= 3:
            return 'D'
        if n >= 20 and n % 11 == 0:
            return 'D'
        return 'C'

    # Opponent heavily defecting: defend strongly, but rarely probe.
    if opp_rate < 0.15:
        if n % 17 == 0:
            return 'C'
        return 'D'

    # Long defect streak: punish.
    if opp_def_streak >= 2:
        if opp_def_streak >= 4:
            return 'D'
        if opp_last == 'D' and opp_rate > 0.3:
            return 'D'
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    # Opponent cooperating but historically mixed.
    if opp_last == 'C':
        # We defected and opponent still cooperated: continue exploiting briefly.
        if my_last == 'D' and opp_coop_streak >= 1:
            if opp_coop_streak >= 2 and opp_rate > 0.4:
                if rng.random() < 0.7:
                    return 'D'
            return 'C'
        # If opponent widely cooperative, mostly cooperate with occasional probes.
        if recent_rate > 0.85:
            remaining = 100 - n
            if remaining <= 2:
                return 'D'
            if n >= 10 and n % 13 == 0:
                return 'D'
            return 'C'
        if recent_rate < 0.5:
            if rng.random() < 0.4:
                return 'D'
            return 'C'
        # Slightly opportunistic against moderately cooperative opponents.
        if n >= 6 and opp_rate > 0.5 and rng.random() < 0.08:
            return 'D'
        return 'C'

    # Opponent defected, but streak is 1 (isolated).
    # Forgive if opponent has been quite cooperative, otherwise retaliate once.
    if opp_rate > 0.65:
        if rng.random() < 0.55:
            return 'C'
        return 'D'
    if recent_rate >= 0.75:
        if rng.random() < 0.4:
            return 'C'
        return 'D'
    return 'D'
